const insertCampaignRecipients = `-- name: InsertCampaignRecipients :execrows
INSERT INTO marketing_recipients (campaign_id, tenant_id, customer_id, address)
SELECT $1, a.tenant_id, a.customer_id,
       CASE WHEN $2::text = 'EMAIL' THEN a.email ELSE a.phone END
FROM marketing_audience a
WHERE a.tenant_id = $3
  AND NOT a.is_blocked
  AND (($2::text = 'EMAIL'    AND a.email <> '' AND a.email_consent    = 'GRANTED')
    OR ($2::text = 'SMS'      AND a.phone <> '' AND a.sms_consent      = 'GRANTED')
    OR ($2::text = 'WHATSAPP' AND a.phone <> '' AND a.whatsapp_consent = 'GRANTED'))
  AND CASE $4::text
        WHEN 'NEW'        THEN a.created_at >= now() - interval '30 days'
        WHEN 'REPEAT'     THEN a.visit_count >= 2
        WHEN 'INACTIVE'   THEN a.visit_count >= 1 AND a.last_visit_at < now() - interval '60 days'
        WHEN 'HIGH_VALUE' THEN a.visit_count >= 4
        ELSE TRUE
      END
ON CONFLICT (campaign_id, customer_id) DO NOTHING
`

type InsertCampaignRecipientsParams struct {
	CampaignID pgtype.UUID `json:"campaign_id"`
	Channel    string      `json:"channel"`
	TenantID   pgtype.UUID `json:"tenant_id"`
	Audience   string      `json:"audience"`
}

// Materialise the recipient snapshot. ON CONFLICT makes a retried
// materialisation a no-op, so a crash between this and the status update
// cannot double a recipient.
func (q *Queries) InsertCampaignRecipients(ctx context.Context, arg InsertCampaignRecipientsParams) (int64, error) {
	result, err := q.db.Exec(ctx, insertCampaignRecipients,
		arg.CampaignID,
		arg.Channel,
		arg.TenantID,
		arg.Audience,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

