const marketingOverview = `-- name: MarketingOverview :one

SELECT
    (SELECT COUNT(*) FROM marketing_campaigns mc WHERE mc.tenant_id = $1)::bigint AS campaigns,
    (SELECT COUNT(*) FROM marketing_campaigns mc WHERE mc.tenant_id = $1
        AND mc.status IN ('SCHEDULED', 'QUEUED', 'RUNNING', 'PAUSED'))::bigint AS active_campaigns,
    (SELECT COALESCE(SUM(mc.sent_count), 0) FROM marketing_campaigns mc WHERE mc.tenant_id = $1)::bigint AS messages_sent,
    (SELECT COALESCE(SUM(mc.failed_count), 0) FROM marketing_campaigns mc WHERE mc.tenant_id = $1)::bigint AS messages_failed,
    (SELECT COUNT(*) FROM marketing_events me WHERE me.tenant_id = $1 AND me.kind = 'VISIT'
        AND me.created_at >= now() - interval '30 days')::bigint AS visits_30d,
    (SELECT COUNT(*) FROM marketing_events me WHERE me.tenant_id = $1 AND me.kind = 'UNSUBSCRIBE'
        AND me.created_at >= now() - interval '30 days')::bigint AS unsubscribes_30d,
    (SELECT COUNT(*) FROM orders o WHERE o.tenant_id = $1 AND o.status <> 'CANCELLED'
        AND (o.marketing_campaign_id IS NOT NULL OR o.marketing_link_id IS NOT NULL OR o.promotion_id IS NOT NULL)
        AND o.created_at >= now() - interval '30 days')::bigint AS attributed_orders_30d,
    (SELECT COALESCE(SUM(o.total), 0) FROM orders o WHERE o.tenant_id = $1 AND o.status <> 'CANCELLED'
        AND (o.marketing_campaign_id IS NOT NULL OR o.marketing_link_id IS NOT NULL OR o.promotion_id IS NOT NULL)
        AND o.created_at >= now() - interval '30 days')::numeric AS attributed_revenue_30d
`

