const previewAudience = `-- name: PreviewAudience :one


SELECT
    COUNT(*)::bigint AS matched,
    COUNT(*) FILTER (WHERE is_blocked)::bigint AS blocked,
    COUNT(*) FILTER (WHERE NOT is_blocked
        AND (($1::text = 'EMAIL' AND email = '')
          OR ($1::text <> 'EMAIL' AND phone = '')))::bigint AS no_address,
    COUNT(*) FILTER (WHERE NOT is_blocked
        AND (($1::text = 'EMAIL'    AND email <> '' AND email_consent    <> 'GRANTED')
          OR ($1::text = 'SMS'      AND phone <> '' AND sms_consent      <> 'GRANTED')
          OR ($1::text = 'WHATSAPP' AND phone <> '' AND whatsapp_consent <> 'GRANTED')))::bigint AS no_consent,
    COUNT(*) FILTER (WHERE NOT is_blocked
        AND (($1::text = 'EMAIL'    AND email <> '' AND email_consent    = 'GRANTED')
          OR ($1::text = 'SMS'      AND phone <> '' AND sms_consent      = 'GRANTED')
          OR ($1::text = 'WHATSAPP' AND phone <> '' AND whatsapp_consent = 'GRANTED')))::bigint AS eligible
FROM marketing_audience
WHERE tenant_id = $2
  AND CASE $3::text
        WHEN 'NEW'        THEN created_at >= now() - interval '30 days'
        WHEN 'REPEAT'     THEN visit_count >= 2
        WHEN 'INACTIVE'   THEN visit_count >= 1 AND last_visit_at < now() - interval '60 days'
        WHEN 'HIGH_VALUE' THEN visit_count >= 4
        ELSE TRUE
      END
`

type PreviewAudienceParams struct {
	Channel  string      `json:"channel"`
	TenantID pgtype.UUID `json:"tenant_id"`
	Audience string      `json:"audience"`
}

type PreviewAudienceRow struct {
	Matched   int64 `json:"matched"`
	Blocked   int64 `json:"blocked"`
	NoAddress int64 `json:"no_address"`
	NoConsent int64 `json:"no_consent"`
	Eligible  int64 `json:"eligible"`
}

// Marketing framework. Every query is tenant-scoped except the worker claims
// and the public /go and unsubscribe lookups, which address a globally unique
// id and read the tenant from the row.
// ---------- audience ----------
// Who a campaign would reach and why the rest are left out. The segment rule
// lives in SQL once (here and in InsertCampaignRecipients, kept identical).
func (q *Queries) PreviewAudience(ctx context.Context, arg PreviewAudienceParams) (PreviewAudienceRow, error) {
	row := q.db.QueryRow(ctx, previewAudience, arg.Channel, arg.TenantID, arg.Audience)
	var i PreviewAudienceRow
	err := row.Scan(
		&i.Matched,
		&i.Blocked,
		&i.NoAddress,
		&i.NoConsent,
		&i.Eligible,
	)
	return i, err
}

