const setCampaignStatus = `-- name: SetCampaignStatus :one
UPDATE marketing_campaigns
SET status = $1, status_reason = $2,
    -- "Send now" takes the database clock, so a worker on the same database
    -- always sees it as due, whatever the API host's clock says.
    scheduled_at = CASE WHEN $3::bool THEN now() ELSE COALESCE($4, scheduled_at) END,
    updated_at = now()
WHERE id = $5 AND tenant_id = $6
  AND status = ANY ($7::text[])
RETURNING id, tenant_id, name, goal, audience, channel, subject, body, button_label, link_id, status, status_reason, scheduled_at, started_at, finished_at, total_count, sent_count, failed_count, skipped_count, created_by, created_at, updated_at, template_name, template_lang, kind, promotion_id, automation_rule_id
`

