const upsertConsent = `-- name: UpsertConsent :exec
INSERT INTO marketing_consents (tenant_id, customer_id, channel, status, source)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (tenant_id, customer_id, channel)
DO UPDATE SET status = EXCLUDED.status, source = EXCLUDED.source, updated_at = now()
`

type UpsertConsentParams struct {
	TenantID   pgtype.UUID `json:"tenant_id"`
	CustomerID pgtype.UUID `json:"customer_id"`
	Channel    string      `json:"channel"`
	Status     string      `json:"status"`
	Source     string      `json:"source"`
}

func (q *Queries) UpsertConsent(ctx context.Context, arg UpsertConsentParams) error {
	_, err := q.db.Exec(ctx, upsertConsent,
		arg.TenantID,
		arg.CustomerID,
		arg.Channel,
		arg.Status,
		arg.Source,
	)
	return err
}
